// Included by the disposable proof Cargo target generated by adapter-smoke.py.
// Every imported implementation is the actual product source. Only the HTTP
// pages, resolver configuration and run-owned profile are fixtures.
use engine::{AgentBrowserTransport, EngineConfig};
use serde_json::{json, Value};
use std::sync::{
    atomic::{AtomicUsize, Ordering},
    Arc,
};
use tokio::io::{AsyncReadExt, AsyncWriteExt};

struct FixtureResolver;
impl policy::Resolver for FixtureResolver {
    fn resolve<'a>(
        &'a self,
        host: &'a str,
        port: u16,
    ) -> browser::BoxFuture<'a, std::io::Result<Vec<std::net::SocketAddr>>> {
        Box::pin(async move {
            eprintln!("Synthetic resolver: {host}:{port}");
            if host == "fixture.invalid" {
                Ok(vec![std::net::SocketAddr::from(([127, 0, 0, 1], port))])
            } else {
                Err(std::io::Error::other(
                    "Fixture blocks every external hostname",
                ))
            }
        })
    }
}

async fn fixture() -> (String, Arc<AtomicUsize>, tokio::task::JoinHandle<()>) {
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let origin = format!(
        "http://fixture.invalid:{}",
        listener.local_addr().unwrap().port()
    );
    let mutations = Arc::new(AtomicUsize::new(0));
    let effects = mutations.clone();
    let task = tokio::spawn(async move {
        loop {
            let (mut stream, _) = listener.accept().await.unwrap();
            let effects = effects.clone();
            tokio::spawn(async move {
                let mut bytes = Vec::new();
                let mut chunk = [0; 4096];
                loop {
                    let count = stream.read(&mut chunk).await.unwrap_or(0);
                    if count == 0 {
                        return;
                    }
                    bytes.extend_from_slice(&chunk[..count]);
                    if bytes.windows(4).any(|part| part == b"\r\n\r\n") {
                        break;
                    }
                    assert!(
                        bytes.len() <= 32768,
                        "Synthetic request headers are bounded"
                    );
                }
                let count = bytes.len();
                let request = String::from_utf8_lossy(&bytes);
                let path = request.split_whitespace().nth(1).unwrap_or("/");
                if let Some(directory) = std::env::var_os("CLOVY_PROOF_EVIDENCE") {
                    use std::io::Write;
                    let mut log = std::fs::OpenOptions::new()
                        .create(true)
                        .append(true)
                        .open(std::path::PathBuf::from(directory).join("fixture-requests.jsonl"))
                        .unwrap();
                    writeln!(log, "{}", json!({"path":path,"bytes":count})).unwrap();
                }
                if path == "/effect" {
                    effects.fetch_add(1, Ordering::SeqCst);
                }
                let title = if request.contains("clovy_synthetic_login=1") {
                    "Synthetic login retained"
                } else {
                    "Synthetic fresh profile"
                };
                let page = format!(
                    r#"<!doctype html><title>{title}</title><h1>{title}</h1>
<form action='/submitted'><label for='q'>Query</label><input id='q' name='q'><button type='submit'>Submit</button></form>
<input type='password' value='synthetic-password-secret'><input autocomplete='one-time-code' value='synthetic-otp-secret'>
<button id='save' type='button'>Save</button><button id='replace' type='button' onclick="save.replaceWith(save.cloneNode(true))">Replace</button>
<button id='hang' type='button' onclick="fetch('/effect',{{method:'POST'}});while(true){{}}">Hang</button>"#
                );
                let response=format!("HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nSet-Cookie: clovy_synthetic_login=1; Path=/; Max-Age=3600; SameSite=Strict\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",page.len(),page);
                let _ = stream.write_all(response.as_bytes()).await;
            });
        }
    });
    (origin, mutations, task)
}
fn reference(snapshot: &Value, name: &str) -> String {
    let line = snapshot["snapshot"]
        .as_str()
        .unwrap()
        .lines()
        .find(|line| line.contains(&format!("\"{name}\"")) && line.contains("ref="))
        .unwrap();
    line.split("ref=")
        .nth(1)
        .unwrap()
        .split(']')
        .next()
        .unwrap()
        .to_owned()
}
async fn call(engine: &AgentBrowserTransport, id: &str, tool: &str, mut args: Value) -> Value {
    args["session_id"] = json!(id);
    engine
        .execute(id, tool, args)
        .await
        .unwrap_or_else(|e| panic!("{tool}: {e:?}"))
}
async fn guarded(
    engine: &AgentBrowserTransport,
    id: &str,
    tab: i64,
    reference: &str,
    operation: &str,
    mut args: Value,
) -> Value {
    let expected = call(
        engine,
        id,
        "inspect_reference",
        json!({"tab_id":tab,"ref":reference}),
    )
    .await;
    args["tab_id"] = json!(tab);
    args["ref"] = json!(reference);
    args["expected"] = expected;
    call(engine, id, operation, args).await
}

const DNS_BOOTSTRAP: usize = 0;
const DNS_PUBLIC: usize = 1;
const DNS_PRIVATE: usize = 2;
const DNS_FAILED: usize = 3;

#[derive(Default)]
struct NetworkControl {
    answer: AtomicUsize,
    effects: AtomicUsize,
    public_validations: AtomicUsize,
}
struct ControlledResolver(Arc<NetworkControl>);
impl policy::Resolver for ControlledResolver {
    fn resolve<'a>(
        &'a self,
        host: &'a str,
        port: u16,
    ) -> browser::BoxFuture<'a, std::io::Result<Vec<std::net::SocketAddr>>> {
        Box::pin(async move {
            let address = match host {
                // Only the synthetic side-effect endpoint needs a fresh
                // connection during the click. The main document is static.
                "effect.invalid" => [127, 0, 0, 1],
                "fixture.invalid" => match self.0.answer.load(Ordering::SeqCst) {
                    DNS_BOOTSTRAP => [127, 0, 0, 1],
                    DNS_PUBLIC => {
                        self.0.public_validations.fetch_add(1, Ordering::SeqCst);
                        [93, 184, 216, 34]
                    }
                    DNS_PRIVATE => [10, 1, 2, 3],
                    DNS_FAILED => {
                        return Err(std::io::Error::other(
                            "synthetic resolver detail must stay private",
                        ));
                    }
                    _ => unreachable!(),
                },
                _ => return Err(std::io::Error::other("Fixture blocks external DNS")),
            };
            Ok(vec![std::net::SocketAddr::from((address, port))])
        })
    }
}

async fn postvalidation_fixture(
    control: Arc<NetworkControl>,
    after: usize,
) -> (String, tokio::task::JoinHandle<()>) {
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let port = listener.local_addr().unwrap().port();
    let origin = format!("http://fixture.invalid:{port}");
    let task = tokio::spawn(async move {
        loop {
            let (mut stream, _) = listener.accept().await.unwrap();
            let control = control.clone();
            tokio::spawn(async move {
                let mut bytes = Vec::new();
                let mut chunk = [0; 4096];
                loop {
                    let count = stream.read(&mut chunk).await.unwrap_or(0);
                    if count == 0 {
                        return;
                    }
                    bytes.extend_from_slice(&chunk[..count]);
                    if bytes.windows(4).any(|part| part == b"\r\n\r\n") {
                        break;
                    }
                    assert!(bytes.len() <= 32768);
                }
                let request = String::from_utf8_lossy(&bytes);
                if request.starts_with("POST /network-effect ") {
                    control.effects.fetch_add(1, Ordering::SeqCst);
                    // The synchronous XHR cannot return to its click handler
                    // until this real server-side effect and DNS flip finish.
                    control.answer.store(after, Ordering::SeqCst);
                }
                let page = format!(
                    r#"<!doctype html><title>Postvalidation fixture</title>
<link rel="icon" href="data:,">
<h1>Postvalidation fixture</h1><button id="commit" type="button" onclick="const xhr = new XMLHttpRequest(); xhr.open('POST', 'http://effect.invalid:{port}/network-effect', false); xhr.send();">Commit fixture effect</button>"#
                );
                // The fixture has no main-origin subresource links. Its CSP
                // confines page connections to the owned side-effect host.
                let response = format!(
                    "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nAccess-Control-Allow-Origin: *\r\nContent-Security-Policy: default-src 'none'; script-src 'unsafe-inline'; connect-src http://effect.invalid:{port}; img-src data:\r\nCache-Control: no-store\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
                    page.len(), page
                );
                let _ = stream.write_all(response.as_bytes()).await;
            });
        }
    });
    (origin, task)
}

async fn postvalidation_network_proof(config: &EngineConfig, evidence: &std::path::Path) -> Value {
    let mut receipts = Vec::new();
    for (label, after) in [("private", DNS_PRIVATE), ("resolver_error", DNS_FAILED)] {
        let control = Arc::new(NetworkControl::default());
        let (origin, server) = postvalidation_fixture(control.clone(), after).await;
        let mut isolated = config.clone();
        isolated.persistent = false;
        isolated.resolver = Arc::new(ControlledResolver(control.clone()));
        let engine = AgentBrowserTransport::new(isolated.clone());
        engine.reserve("postvalidation").unwrap();
        let tab = call(&engine, "postvalidation", "start_session", json!({})).await["tabId"]
            .as_i64()
            .unwrap();
        call(
            &engine,
            "postvalidation",
            "navigate",
            json!({"tab_id":tab,"url":origin}),
        )
        .await;
        let snapshot = call(&engine, "postvalidation", "snapshot", json!({"tab_id":tab})).await;
        let target = reference(&snapshot, "Commit fixture effect");
        // The last pre-action inspection is accepted with a genuinely public
        // answer, independently of the permitted loopback fixture connection.
        control.answer.store(DNS_PUBLIC, Ordering::SeqCst);
        let expected = call(
            &engine,
            "postvalidation",
            "inspect_reference",
            json!({"tab_id":tab,"ref":target}),
        )
        .await;
        assert!(control.public_validations.load(Ordering::SeqCst) > 0);
        assert_eq!(control.effects.load(Ordering::SeqCst), 0);
        let args = json!({"tab_id":tab,"ref":target,"expected":expected});
        let error = engine
            .execute("postvalidation", "click", args.clone())
            .await
            .unwrap_err();
        std::fs::write(
            evidence.join(format!("postvalidation-{label}-observed.json")),
            serde_json::to_vec_pretty(&json!({
                "counter":control.effects.load(Ordering::SeqCst),
                "code":error.code,
                "safeMessage":error.message,
                "publicValidationsBefore":control.public_validations.load(Ordering::SeqCst),
                "taskClosed":engine.state("postvalidation").is_err()
            }))
            .unwrap(),
        )
        .unwrap();
        assert_eq!(control.effects.load(Ordering::SeqCst), 1);
        assert_eq!(error.code, "browser_outcome_unknown");
        assert!(error.message.contains("browser_network_blocked"));
        assert!(error.message.to_ascii_lowercase().contains("do not repeat"));
        assert!(!error.message.contains("synthetic resolver detail"));
        assert_eq!(
            engine.state("postvalidation").unwrap_err().code,
            "browser_session_closed"
        );
        assert_eq!(
            engine
                .execute("postvalidation", "click", args)
                .await
                .unwrap_err()
                .code,
            "browser_session_closed"
        );
        assert_eq!(control.effects.load(Ordering::SeqCst), 1);
        receipts.push(json!({"case":format!("post-delivery-{label}"),"counter":1,"code":error.code,"safeCause":"browser_network_blocked","oldHandlesInvalid":true,"replayCounter":1}));
        engine.shutdown();

        // The same failure before navigate dispatch is a definite refusal and
        // must neither deliver the fixture effect nor close an otherwise live task.
        control.effects.store(0, Ordering::SeqCst);
        let engine = AgentBrowserTransport::new(isolated.clone());
        engine.reserve("prevalidation").unwrap();
        let tab = call(&engine, "prevalidation", "start_session", json!({})).await["tabId"]
            .as_i64()
            .unwrap();
        let error = engine
            .execute(
                "prevalidation",
                "navigate",
                json!({"tab_id":tab,"url":origin}),
            )
            .await
            .unwrap_err();
        assert_eq!(error.code, "browser_network_blocked");
        assert!(engine.state("prevalidation").is_ok());
        assert_eq!(control.effects.load(Ordering::SeqCst), 0);
        receipts
            .push(json!({"case":format!("pre-dispatch-{label}"),"counter":0,"code":error.code}));
        engine.shutdown();

        // Read-only responses can still refuse a bad post-check: they do not
        // claim an uncertain mutation, but the invalid task must stop.
        control.answer.store(DNS_BOOTSTRAP, Ordering::SeqCst);
        let engine = AgentBrowserTransport::new(isolated);
        engine.reserve("read-validation").unwrap();
        let tab = call(&engine, "read-validation", "start_session", json!({})).await["tabId"]
            .as_i64()
            .unwrap();
        call(
            &engine,
            "read-validation",
            "navigate",
            json!({"tab_id":tab,"url":origin}),
        )
        .await;
        control.answer.store(after, Ordering::SeqCst);
        let error = engine
            .execute("read-validation", "snapshot", json!({"tab_id":tab}))
            .await
            .unwrap_err();
        assert_eq!(error.code, "browser_network_blocked");
        assert_eq!(
            engine.state("read-validation").unwrap_err().code,
            "browser_session_closed"
        );
        assert_eq!(control.effects.load(Ordering::SeqCst), 0);
        receipts.push(json!({"case":format!("read-only-{label}"),"counter":0,"code":error.code,"oldHandlesInvalid":true}));
        engine.shutdown();
        server.abort();
    }
    let result = json!({"passed":true,"receipts":receipts});
    std::fs::write(
        evidence.join("postvalidation-network.json"),
        serde_json::to_vec_pretty(&result).unwrap(),
    )
    .unwrap();
    result
}
#[tokio::main]
async fn main() {
    let resource = std::path::PathBuf::from(std::env::var_os("CLOVY_PROOF_RESOURCES").unwrap());
    let evidence = std::path::PathBuf::from(std::env::var_os("CLOVY_PROOF_EVIDENCE").unwrap());
    std::fs::create_dir_all(&evidence).unwrap();
    let data = evidence.join(format!("profile-{}", uuid::Uuid::new_v4()));
    let mut config = EngineConfig::production(resource, data.clone(), true);
    config.policy.allow_loopback = true;
    config.resolver = Arc::new(FixtureResolver);
    let engine = AgentBrowserTransport::new(config.clone());
    let (origin, effects, server) = fixture().await;
    // Exercise the actual connection proxy independently before involving
    // Chrome. This narrows a failed real navigation without substituting a
    // different proxy in the browser's path.
    let preflight = proxy::PinningProxy::start(config.resolver.clone(), config.policy.clone())
        .await
        .unwrap();
    let mut request = tokio::net::TcpStream::connect(("127.0.0.1", preflight.port()))
        .await
        .unwrap();
    request
        .write_all(
            format!(
                "GET {origin}/ HTTP/1.1\r\nHost: {}\r\n\r\n",
                origin.trim_start_matches("http://")
            )
            .as_bytes(),
        )
        .await
        .unwrap();
    let mut response = Vec::new();
    tokio::time::timeout(
        std::time::Duration::from_secs(5),
        request.read_to_end(&mut response),
    )
    .await
    .unwrap()
    .unwrap();
    assert!(String::from_utf8_lossy(&response).contains("Synthetic fresh profile"));
    std::fs::write(
        evidence.join("proxy-preflight.json"),
        json!({"passed":true,"responseBytes":response.len()}).to_string(),
    )
    .unwrap();
    preflight.shutdown();
    engine.reserve("task-a").unwrap();
    assert_eq!(
        engine.reserve("task-b").unwrap_err().code,
        "browser_profile_busy"
    );
    let tab = call(&engine, "task-a", "start_session", json!({})).await["tabId"]
        .as_i64()
        .unwrap();
    call(
        &engine,
        "task-a",
        "navigate",
        json!({"tab_id":tab,"url":origin}),
    )
    .await;
    let first = call(&engine, "task-a", "snapshot", json!({"tab_id":tab})).await;
    std::fs::write(
        evidence.join("first-snapshot.json"),
        serde_json::to_vec_pretty(&first).unwrap(),
    )
    .unwrap();
    let query = reference(&first, "Query");
    guarded(
        &engine,
        "task-a",
        tab,
        &query,
        "fill",
        json!({"text":"synthetic query"}),
    )
    .await;
    let snapshot = call(&engine, "task-a", "snapshot", json!({"tab_id":tab})).await;
    for value in [
        "synthetic-password-secret",
        "synthetic-otp-secret",
        "synthetic query",
    ] {
        assert!(!snapshot.to_string().contains(value));
    }
    std::fs::write(
        evidence.join("snapshot.json"),
        serde_json::to_vec_pretty(&snapshot).unwrap(),
    )
    .unwrap();
    let image = call(&engine, "task-a", "screenshot", json!({"tab_id":tab})).await;
    use base64::Engine;
    let png = base64::engine::general_purpose::STANDARD
        .decode(image["base64"].as_str().unwrap())
        .unwrap();
    assert!(png.starts_with(b"\x89PNG\r\n\x1a\n"));
    std::fs::write(evidence.join("screenshot.png"), png).unwrap();
    let save = reference(&snapshot, "Save");
    let expected = call(
        &engine,
        "task-a",
        "inspect_reference",
        json!({"tab_id":tab,"ref":save}),
    )
    .await;
    guarded(
        &engine,
        "task-a",
        tab,
        &reference(&snapshot, "Replace"),
        "click",
        json!({}),
    )
    .await;
    let stale = engine
        .execute(
            "task-a",
            "click",
            json!({"tab_id":tab,"ref":save,"expected":expected}),
        )
        .await
        .unwrap_err();
    assert_eq!(stale.code, "stale_reference");
    let snapshot = call(&engine, "task-a", "snapshot", json!({"tab_id":tab})).await;
    guarded(
        &engine,
        "task-a",
        tab,
        &reference(&snapshot, "Query"),
        "press",
        json!({"key":"Enter"}),
    )
    .await;
    assert!(
        call(&engine, "task-a", "snapshot", json!({"tab_id":tab})).await["url"]
            .as_str()
            .unwrap()
            .contains("submitted")
    );
    call(&engine, "task-a", "back", json!({"tab_id":tab})).await;
    let second = call(
        &engine,
        "task-a",
        "open_tab",
        json!({"url":format!("{origin}/second")}),
    )
    .await["tabId"]
        .as_i64()
        .unwrap();
    assert_ne!(tab, second);
    assert_eq!(
        call(&engine, "task-a", "list_tabs", json!({})).await["tabs"]
            .as_array()
            .unwrap()
            .len(),
        2
    );
    call(&engine, "task-a", "switch_tab", json!({"tab_id":tab})).await;
    call(&engine, "task-a", "close_tab", json!({"tab_id":second})).await;
    assert_eq!(
        engine
            .execute("task-a", "snapshot", json!({"tab_id":second}))
            .await
            .unwrap_err()
            .code,
        "tab_gone"
    );
    assert_eq!(
        engine
            .execute(
                "task-a",
                "navigate",
                json!({"tab_id":tab,"url":"http://10.1.2.3/"})
            )
            .await
            .unwrap_err()
            .code,
        "browser_network_blocked"
    );
    let human = engine.takeover("task-a").await.unwrap();
    assert!(human["suspended"].as_bool().unwrap());
    assert_eq!(
        engine
            .execute("task-a", "snapshot", json!({"tab_id":tab}))
            .await
            .unwrap_err()
            .code,
        "browser_human_takeover"
    );
    engine.resume("task-a").await.unwrap();
    let human_tab = human["tabId"].as_i64().unwrap();
    assert_ne!(human_tab, tab);
    call(
        &engine,
        "task-a",
        "navigate",
        json!({"tab_id":human_tab,"url":origin}),
    )
    .await;
    assert!(
        call(&engine, "task-a", "snapshot", json!({"tab_id":human_tab}))
            .await
            .to_string()
            .contains("Synthetic login retained")
    );
    engine.terminate("task-a");
    assert!(data.join("browser-profile").is_dir());
    engine.reserve("task-new-run").unwrap();
    let reopened = call(&engine, "task-new-run", "start_session", json!({})).await["tabId"]
        .as_i64()
        .unwrap();
    call(
        &engine,
        "task-new-run",
        "navigate",
        json!({"tab_id":reopened,"url":origin}),
    )
    .await;
    let snapshot = call(
        &engine,
        "task-new-run",
        "snapshot",
        json!({"tab_id":reopened}),
    )
    .await;
    assert!(snapshot.to_string().contains("Synthetic login retained"));
    // Real in-flight mutation: renderer hangs after sending one request.
    // Stop closes the private pipes and returns unknown; no replay follows.
    let hang = reference(&snapshot, "Hang");
    let expected = call(
        &engine,
        "task-new-run",
        "inspect_reference",
        json!({"tab_id":reopened,"ref":hang}),
    )
    .await;
    let worker = engine.clone();
    let action = tokio::spawn(async move {
        worker
            .execute(
                "task-new-run",
                "click",
                json!({"tab_id":reopened,"ref":hang,"expected":expected}),
            )
            .await
    });
    for _ in 0..100 {
        if effects.load(Ordering::SeqCst) > 0 {
            break;
        }
        tokio::time::sleep(std::time::Duration::from_millis(20)).await;
    }
    assert_eq!(effects.load(Ordering::SeqCst), 1);
    engine.terminate("task-new-run");
    assert_eq!(
        action.await.unwrap().unwrap_err().code,
        "browser_outcome_unknown"
    );
    assert_eq!(effects.load(Ordering::SeqCst), 1);
    // Cancellation races actual engine/Chrome startup repeatedly. Every slot
    // was published before async startup; closing it cannot resurrect it.
    for iteration in 0..3 {
        let id = format!("startup-{iteration}");
        engine.reserve(&id).unwrap();
        let worker = engine.clone();
        let name = id.clone();
        let startup =
            tokio::spawn(async move { worker.execute(&name, "start_session", json!({})).await });
        tokio::time::sleep(std::time::Duration::from_millis(15)).await;
        engine.terminate(&id);
        assert!(startup.await.unwrap().is_err());
    }
    // Production defaults cannot access even this fixture.
    let mut restricted = config.clone();
    restricted.persistent = false;
    restricted.policy.allow_loopback = false;
    let restricted = AgentBrowserTransport::new(restricted);
    restricted.reserve("routine").unwrap();
    let routine = call(&restricted, "routine", "start_session", json!({})).await["tabId"]
        .as_i64()
        .unwrap();
    assert_eq!(
        restricted
            .execute(
                "routine",
                "navigate",
                json!({"tab_id":routine,"url":origin})
            )
            .await
            .unwrap_err()
            .code,
        "browser_network_blocked"
    );
    restricted.shutdown();
    server.abort();
    engine.shutdown();
    let postvalidation = postvalidation_network_proof(&config, &evidence).await;
    std::fs::write(evidence.join("adapter-result.json"),json!({"passed":true,"mutations":effects.load(Ordering::SeqCst),"retainedProfile":data,"postvalidationNetwork":postvalidation,"cases":["private host","real adapter","navigate","snapshot sanitized","screenshot","fill","press","back","tabs","replaced node refused","closed tab refused","profile lease","human takeover","resume","profile reopen","stop during mutation unknown no replay","cancel startup","production network guard","post-delivery private DNS unknown","post-delivery resolver error unknown","pre-dispatch DNS refusal","read-only postvalidation refusal"]}).to_string()).unwrap();
    println!(
        "Real adapter proof passed; effect counters matched, no replay. Evidence: {}",
        evidence.display()
    );
}
